const reverseString = (str) => {
  let reversed = '';
  const inputLength = str.length;

  if (inputLength === 0) {
    return `The input string "${str}" is empty.`;
  }

  for (let i = inputLength - 1; i >= 0; i--) {
    reversed += str[i];
  }

  const originalFirstChar = str[0];
  const originalLastChar = str[inputLength - 1];
  const reversedFirstChar = reversed[0];
  const reversedLastChar = reversed[reversed.length - 1];

  console.log(`Original string: "${str}"`);
  console.log(`Length of original string: ${inputLength}`);
  console.log(`First character of original: ${originalFirstChar}`);
  console.log(`Last character of original: ${originalLastChar}`);
  console.log(`Reversed string: "${reversed}"`);
  console.log(`First character of reversed: ${reversedFirstChar}`);
  console.log(`Last character of reversed: ${reversedLastChar}`);

  return reversed;
};

