function calculateFactorial(n) {
  if (n < 0) {
    throw new Error(`Input must be a non-negative integer. Received: ${n}`);
  }

  if (n === 0) {
    console.log(`Calculating factorial for ${n}, which is 1.`);
    return 1;
  }

  let result = 1;
  let calculationSteps = [];

  for (let i = 1; i <= n; i++) {
    result *= i;
    calculationSteps.push(`${i}`);
  }

  const stepsString = calculationSteps.join(` * `);
  console.log(`Calculating factorial for ${n}: ${stepsString} = ${result}`);

  const finalMessage = `The factorial of ${n} is indeed ${result}.`;
  console.log(finalMessage);

  return result;
}

