const celsiusToFahrenheit = (celsius) => {
  const conversionFactor = 9 / 5;
  const offset = 32;

  const fahrenheit = celsius * conversionFactor + offset;

  console.log(`${celsius}°C is equivalent to ${fahrenheit}°F.`);

  if (celsius < -273.15) {
    console.warn(`Temperature ${celsius}°C is below absolute zero.`);
  }

  const roundedFahrenheit = Math.round(fahrenheit * 100) / 100;

  if (fahrenheit !== roundedFahrenheit) {
    console.log(`The unrounded value was ${fahrenheit}°F.`);
  }

  const conversionMessage = `Calculated ${celsius}°C to ${roundedFahrenheit}°F.`;
  console.log(conversionMessage);

  return roundedFahrenheit;
};

