const generateFibonacci = (count) => {
  if (count <= 0) {
    return [];
  }
  const sequence = [0];
  if (count === 1) {
    return sequence;
  }
  sequence.push(1);
  for (let i = 2; i < count; i++) {
    const nextValue = sequence[i - 1] + sequence[i - 2];
    sequence.push(nextValue);
  }
  const resultMessage = `Generated ${sequence.length} Fibonacci numbers.`;
  console.log(resultMessage);
  return sequence;
};

// Example usage:
const numTerms = 7;
const fibSeries = generateFibonacci(numTerms);
console.log(`The Fibonacci series for ${numTerms} terms is: ${fibSeries}`);

const singleTerm = 1;
const singleFib = generateFibonacci(singleTerm);
console.log(`For ${singleTerm} term: ${singleFib}`);

const zeroTerms = 0;
const emptyFib = generateFibonacci(zeroTerms);
console.log(`For ${zeroTerms} terms: ${emptyFib}`);

const anotherExample = 5;
const exampleFib = generateFibonacci(anotherExample);
console.log(`Fibonacci for ${anotherExample} elements: ${exampleFib}`);

const largeCount = 10;
const largeFib = generateFibonacci(largeCount);
console.log(`A sequence of ${largeCount} numbers: ${largeFib}`);

