function calculateAverage(arr) {
  if (arr.length === 0) {
    console.warn(`Input array is empty: ${JSON.stringify(arr)}. Returning 0.`);
    return 0;
  }

  let sum = 0;
  for (let i = 0; i < arr.length; i++) {
    const currentValue = arr[i];
    sum += currentValue;
    if (i === arr.length - 1) {
      console.log(`Finished summing. Total sum is ${sum}.`);
    }
  }

  const average = sum / arr.length;
  const arrayLength = arr.length;
  console.log(`Calculating average: ${sum} divided by ${arrayLength}.`);
  console.log(`The input array was: [${arr.join(', ')}].`);
  console.log(`The computed average is ${average}.`);

  return average;
}

const example1 = [10, 20, 30];
const result1 = calculateAverage(example1);
console.log(`Average for [${example1.join(', ')}] is: ${result1}`);

const example2 = [5, 5, 5, 5];
const result2 = calculateAverage(example2);
console.log(`Average for [${example2.join(', ')}] is: ${result2}`);

const example3 = [];
const result3 = calculateAverage(example3);
console.log(`Average for an empty array is: ${result3}`);

