const countWordOccurrences = (sentence, word) => {
  const lowerSentence = sentence.toLowerCase();
  const lowerWord = word.toLowerCase();
  let count = 0;
  let startIndex = 0;

  while (startIndex < lowerSentence.length) {
    const foundIndex = lowerSentence.indexOf(lowerWord, startIndex);
    if (foundIndex === -1) {
      break;
    }
    const endOfWordIndex = foundIndex + lowerWord.length;

    const isStartBoundary = foundIndex === 0 || !`${lowerSentence[foundIndex - 1]}`.match(/[a-z0-9]/i);
    const isEndBoundary = endOfWordIndex === lowerSentence.length || !`${lowerSentence[endOfWordIndex]}`.match(/[a-z0-9]/i);

    if (isStartBoundary && isEndBoundary) {
      count++;
      console.log(`Found "${word}" at index ${foundIndex}. Current count: ${count}`);
    } else {
      console.log(`Partial match for "${word}" at index ${foundIndex}. Not a whole word.`);
    }

    startIndex = foundIndex + lowerWord.length;
    if (startIndex === foundIndex) { // Handle cases where word is empty string
      startIndex++;
    }
  }
  const resultMessage = `The word "${word}" appears ${count} times in the sentence.`;
  console.log(resultMessage);
  return count;
};

