const test2 = areAnagrams('hello', 'world');   // false
const test3 = areAnagrams('Debit card', 'Bad credit'); // true
const test4 = areAnagrams('A gentleman', 'Elegant man'); // true
const test5 = areAnagrams('Dormitory', 'Dirty room'); // true
const test6 = areAnagrams('rail safety', 'fairy tales'); // true

