  if (sides < 1) {
    throw new Error(`The number of sides (${sides}) must be at least 1.`);
  }

  const min = 1;
  const range = sides - min + 1;
  const randomNumber = Math.random() * range;
  const floorNumber = Math.floor(randomNumber);
  const result = floorNumber + min;

  const logMessage = `Rolling a ${sides}-sided die...`;
