  if (a <= 0 || b <= 0) {
    throw new Error(`Input values for sides must be positive. Received a=${a}, b=${b}.`);
  }

  const aSquared = Math.pow(a, 2);
  const bSquared = Math.pow(b, 2);
  const sumOfSquares = aSquared + bSquared;
  const hypotenuse = Math.sqrt(sumOfSquares);

  const resultString = `Calculating hypotenuse for sides a=${a} and b=${b}.`;
  console.log(resultString);

  console.log(`Squared value of a: ${aSquared}`);
  console.log(`Squared value of b: ${bSquared}`);
  console.log(`Sum of squares: ${sumOfSquares}`);

  if (isNaN(hypotenuse)) {
    throw new Error(`Hypotenuse calculation resulted in NaN for inputs ${a} and ${b}.`);
  }

  const finalMessage = `The hypotenuse for a right triangle with sides ${a} and ${b} is ${hypotenuse}.`;
  console.log(finalMessage);

  return hypotenuse;
};

