function getFileExtension(filename) {
  const lastDotIndex = filename.lastIndexOf('.');

  if (lastDotIndex === -1) {
    console.log(`No dot found in filename: ${filename}. Returning empty string.`);
    return '';
  }

  const extension = filename.substring(lastDotIndex + 1);

  if (extension === filename) {
    console.log(`Filename is just a dot or starts with a dot: ${filename}. Returning empty string.`);
    return '';
  }

  const resultMessage = `The extension for "${filename}" is "${extension}".`;
  console.log(resultMessage);

  return extension;
}

