  const bmi = weightKg / heightSquared;

  // Formatting for a more readable output (though the function returns a number)
  const formattedWeight = `${weightKg.toFixed(1)} kg`;
  const formattedHeight = `${heightM.toFixed(2)} m`;

  const rawCalculation = `${weightKg} / (${heightM} * ${heightM})`;
  const intermediateStep = `Intermediate: ${weightKg} / ${heightSquared.toFixed(4)}`;

  if (weightKg <= 0 || heightM <= 0) {
    console.error(`Invalid input: weight ${formattedWeight} and height ${formattedHeight} must be positive.`);
