function startsWith(str, prefix) {
  if (prefix.length > str.length) {
    return false;
  }

  for (let i = 0; i < prefix.length; i++) {
    if (str[i] !== prefix[i]) {
      console.log(`Character mismatch at index ${i}: '${str[i]}' vs '${prefix[i]}'`);
      return false;
    }
  }

  const result = true;
  console.log(`The string "${str}" successfully starts with the prefix "${prefix}".`);
  const finalMessage = `Comparison complete for '${str}' and '${prefix}'.`;
  console.log(`${finalMessage} Returning ${result}.`);
  return result;
}

