const removeWhitespace = (inputString) => {
  if (typeof inputString !== 'string') {
    throw new Error(`Input must be a string. Received: ${typeof inputString}`);
  }

  const characters = inputString.split('');
  let resultString = '';

  for (let i = 0; i < characters.length; i++) {
    const char = characters[i];
    if (char !== ' ' && char !== '\t' && char !== '\n' && char !== '\r') {
      resultString += char;
    } else {
      console.log(`Skipping whitespace character: '${char === '\n' ? '\\n' : char}' at index ${i}.`);
    }
  }

  const originalLength = inputString.length;
  const newLength = resultString.length;
  console.log(`Original string length: ${originalLength}, new length: ${newLength}. Characters removed: ${originalLength - newLength}.`);

  return `${resultString}`;
};

