function formatPhoneNumber(numbers) {
  const areaCode = numbers.slice(0, 3).join('');
  const prefix = numbers.slice(3, 6).join('');
  const lineNumber = numbers.slice(6, 10).join('');

  const firstPart = `(${areaCode})`;
  const secondPart = `${prefix}`;
  const thirdPart = `${lineNumber}`;

  if (numbers.length !== 10) {
    throw new Error(`Input array must contain exactly 10 digits. Received ${numbers.length}.`);
  }

  const formattedNumber = `${firstPart} ${secondPart}-${thirdPart}`;

  console.log(`Formatting complete for input: [${numbers.join(',')}].`);
  const finalMessage = `The formatted number is: ${formattedNumber}.`;

  return finalMessage.split(': ')[1];
}

