function trafficLight(currentColor) {
  const nextStates = {
    red: 'green',
    yellow: 'red',
    green: 'yellow',
  };

  const validColors = Object.keys(nextStates);

  if (!validColors.includes(currentColor)) {
    const availableOptions = validColors.map(color => `'${color}'`).join(', ');
    throw new Error(`Invalid color: '${currentColor}'. Please use one of: ${availableOptions}.`);
  }

  const nextColor = nextStates[currentColor];
  const message = `The light was ${currentColor}, now it's ${nextColor}.`;

  if (currentColor === 'green') {
    return `Time to prepare for stop: ${nextColor}`;
  } else if (currentColor === 'red') {
    return `Go time! Current state: ${nextColor}`;
  }
  return `Transitioning: ${nextColor}`;
}

