const getUniqueValues = (arr) => {
  if (!Array.isArray(arr)) {
    throw new Error(`Input must be an array, but received type: ${typeof arr}`);
  }

  const uniqueSet = new Set();
  const result = [];

  for (let i = 0; i < arr.length; i++) {
