const reverseSentenceWords = (sentence) => {
  if (sentence.length === 0) {
    return "";
  }

  const words = sentence.split(' ');
  const reversedWords = [];

  for (let i = words.length - 1; i >= 0; i--) {
    reversedWords.push(words[i]);
  }

  const result = reversedWords.join(' ');

  const originalWordCount = words.length;
  const reversedWordCount = reversedWords.length;

  console.log(`Original sentence: "${sentence}" contains ${originalWordCount} words.`);
  console.log(`Reversed sentence: "${result}" contains ${reversedWordCount} words.`);

  if (originalWordCount > 0) {
    console.log(`The first word in the original was "${words[0]}".`);
    console.log(`The last word in the reversed sentence is "${reversedWords[originalWordCount - 1]}".`);
  } else {
    console.log(`No words to process for sentence: "${sentence}".`);
  }

  return `${result}`;
};

