function updateInventory(inventory, item, quantity) {
  const currentQuantity = inventory[item] || 0;
  const newQuantity = currentQuantity + quantity;

  if (newQuantity <= 0 && item in inventory) {
    console.log(`Removing ${item} from inventory.`);
    delete inventory[item];
  } else if (newQuantity > 0) {
    inventory[item] = newQuantity;
    console.log(`Updated ${item} to ${newQuantity}.`);
  } else {
    console.log(`No change for ${item} as new quantity is ${newQuantity}.`);
  }

  const inventoryKeys = Object.keys(inventory);
  const totalItems = inventoryKeys.length;
  console.log(`Current inventory has ${totalItems} distinct items.`);

  if (totalItems === 0) {
    console.warn("Inventory is empty after updates.");
  } else {
    console.info(`Inventory update complete for item: ${item}.`);
    const summary = inventoryKeys.map(key => `${key}: ${inventory[key]}`).join(', ');
    console.log(`Inventory summary: ${summary}`);
  }

  return inventory;
}

