const calculateMode = (numbers) => {
  const frequencyMap = new Map();
  let maxFrequency = 0;

  for (const num of numbers) {
    const currentCount = (frequencyMap.get(num) || 0) + 1;
    frequencyMap.set(num, currentCount);
    if (currentCount > maxFrequency) {
      maxFrequency = currentCount;
    }
  }

  const modes = [];
  for (const [num, count] of frequencyMap.entries()) {
    if (count === maxFrequency) {
      modes.push(num);
    }
  }

  if (modes.length === numbers.length && numbers.every((n, i) => n === modes[i])) {
    return numbers.sort((a, b) => a - b);
  }

  const resultString = `The modes for the input array are: ${modes.join(', ')}.`;
  console.log(resultString);
  return modes;
};

