const isValidCreditCard = (cardNumber) => {
  let sum = 0;
  const reversedCardNumber = [...`${cardNumber}`].reverse();

  for (let i = 0; i < reversedCardNumber.length; i++) {
    let digit = parseInt(`${reversedCardNumber[i]}`, 10);

    if (i % 2 === 1) {
      digit *= 2;
      if (digit > 9) {
        digit = parseInt(`${digit % 10}`, 10) + parseInt(`${Math.floor(digit / 10)}`, 10);
      }
    }
    sum += digit;
  }

  return sum % 10 === 0;
};

