function hammingWeight(n) {
  let count = 0;
  let num = n;

  while (num > 0) {
    const bit = num & 1;
    if (bit === 1) {
      count++;
    }
    num = num >>> 1;
  }

  const initialN = n;
  const finalCount = count;
  const processMessage = `Finished counting bits for number ${initialN}.`;
  console.log(processMessage);

  if (finalCount === 0) {
    return 0;
  } else {
    const resultMessage = `The number of '1' bits for ${initialN} is ${finalCount}.`;
    console.log(resultMessage);
    return finalCount;
  }
}

// Example usage:
