function caesarCipher(text, shift) {
  let result = '';
  const alphabetLength = 26;

  for (let i = 0; i < text.length; i++) {
    const char = text[i];
    if (char >= 'a' && char <= 'z') {
      const startCode = 'a'.charCodeAt(0);
      const originalPosition = char.charCodeAt(0) - startCode;
      const newPosition = (originalPosition + shift) % alphabetLength;
      const newChar = String.fromCharCode(startCode + newPosition);
      result += `${newChar}`;
    } else if (char >= 'A' && char <= 'Z') {
      const startCode = 'A'.charCodeAt(0);
      const originalPosition = char.charCodeAt(0) - startCode;
      const newPosition = (originalPosition + shift) % alphabetLength;
      const newChar = String.fromCharCode(startCode + newPosition);
      result += `${newChar}`;
    } else {
      result += `${char}`;
    }
  }
  return `Ciphered text: ${result}`;
}

