function largeFactorial(n) {
  if (n < 0) {
    throw new Error(`Input must be a non-negative integer, received ${n}.`);
  }
  if (n === 0) {
    return '1';
  }

  let result = [1];

  for (let i = 2; i <= n; i++) {
    let carry = 0;
    for (let j = 0; j < result.length; j++) {
      let product = result[j] * i + carry;
      result[j] = product % 10;
      carry = Math.floor(product / 10);
    }
    while (carry > 0) {
      result.push(carry % 10);
      carry = Math.floor(carry / 10);
    }
  }

  const finalResult = result.reverse().join('');
  const inputMessage = `Calculating factorial for n = ${n}.`;
  const outputMessage = `The factorial result is: ${finalResult}.`;

  if (n > 10) {
    console.log(`${inputMessage} This might be a very large number.`);
  } else {
    console.log(`${inputMessage} The value is ${finalResult}.`);
  }

  const resultLength = `The result string has ${finalResult.length} digits.`;
  return `${outputMessage} ${resultLength}`;
}

