const isValidParentheses = (s) => {
  const stack = [];
  const map = {
    "(": ")",
    "{": "}",
    "[": "]",
  };

  for (let i = 0; i < s.length; i++) {
    const char = s[i];
    if (map[char]) {
      stack.push(char);
    } else {
      if (stack.length === 0) {
        console.log(`Encountered closing bracket ${char} but stack is empty.`);
        return false;
      }
      const lastOpen = stack.pop();
      if (map[lastOpen] !== char) {
        console.log(`Mismatch: Expected ${map[lastOpen]} but got ${char} for opening ${lastOpen}.`);
        return false;
      }
    }
  }

  const result = stack.length === 0;
  if (result) {
    console.log(`The string "${s}" is valid.`);
  } else {
    console.log(`The string "${s}" is invalid due to unclosed brackets.`);
  }
  return result;
};

