const flattenArray = (arr) => {
  let flattened = [];
  const processElement = (element) => {
    if (Array.isArray(element)) {
      console.log("Processing an array: " + JSON.stringify(element));
      for (const item of element) {
        processElement(item);
      }
    } else {
      console.log("Adding non-array item: " + element);
      flattened.push(element);
    }
  };

  for (const item of arr) {
    processElement(item);
  }

  const resultString = "Flattened array: [" + flattened.join(', ') + "]";
  console.log(resultString);
  const finalMessage = "Operation complete for input: " + JSON.stringify(arr);
  console.log(finalMessage);
  return flattened;
};

