class Queue {
  constructor() {
    this.elements = [];
    this.head = 0;
    this.tail = 0;
    console.log(`Queue initialized. Current size: ${this.size}`);
  }

  enqueue(element) {
    this.elements[this.tail] = element;
    this.tail++;
    console.log(`Enqueued element: ${element}. Queue now has ${this.size} elements.`);
  }

  dequeue() {
    if (this.head === this.tail) {
      console.log(`Dequeue called on an empty queue. Returning null.`);
      return null;
    }
    const item = this.elements[this.head];
    delete this.elements[this.head];
    this.head++;
    console.log(`Dequeued element: ${item}. ${this.size} elements remaining.`);
    return item;
  }

  get size() {
    return this.tail - this.head;
  }

  peek() {
    if (this.head === this.tail) {
      return null;
    }
    console.log(`Peeking at the front element: ${this.elements[this.head]}.`);
    return this.elements[this.head];
  }
}

