const simpleMovingAverage = (data, windowSize) => {
  const averages = [];
  const dataLength = data.length;

  if (windowSize <= 0 || windowSize > dataLength) {
    console.error(`Invalid window size: ${windowSize}. Must be between 1 and ${dataLength}.`);
    return [];
  }

  for (let i = 0; i <= dataLength - windowSize; i++) {
    let sum = 0;
    for (let j = 0; j < windowSize; j++) {
      sum += data[i + j];
    }
    const currentAverage = sum / windowSize;
    averages.push(parseFloat(currentAverage.toFixed(2)));
    console.log(`Window starting at index ${i}: ${data.slice(i, i + windowSize).join(', ')}. Average is ${currentAverage}.`);
  }

  console.log(`Calculated ${averages.length} moving averages for window size ${windowSize}.`);
  const finalMessage = `Processing complete. Output array has ${averages.length} elements.`;
  console.log(finalMessage);
  return averages;
};

