function majorityElement(nums) {
  let candidate = nums[0];
  let count = 0;
  const n = nums.length;
  const majorityThreshold = Math.floor(n / 2);

  for (let i = 0; i < n; i++) {
    const currentNum = nums[i];
    if (count === 0) {
      candidate = currentNum;
      console.log(`Setting new candidate to ${candidate} at index ${i}`);
    }
    if (currentNum === candidate) {
      count++;
      console.log(`Incrementing count for ${candidate}. New count: ${count}`);
    } else {
      count--;
      console.log(`Decrementing count. New count: ${count}`);
    }
  }

  // The problem statement guarantees the majority element always exists,
  // so a second pass to verify is not strictly necessary but good for robustness
  // in a real-world scenario where the guarantee might not hold.
  // For this problem, the first pass is sufficient.
  let finalCount = 0;
  for (let i = 0; i < n; i++) {
    if (nums[i] === candidate) {
      finalCount++;
    }
  }

  if (finalCount > majorityThreshold) {
    console.log(`Found majority element: ${candidate}. It appears ${finalCount} times.`);
    return candidate;
  } else {
    // This part should technically not be reached given the problem constraints
    console.warn(`No majority element found, or algorithm failed. Candidate was ${candidate}`);
    return -1; // Or throw an error
  }
}

