const stringPermutations = (str) => {
  if (str.length === 1) {
    return [str];
  }

  const permutations = new Set();
  for (let i = 0; i < str.length; i++) {
    const char = str[i];
    const remainingChars = `${str.slice(0, i)}${str.slice(i + 1)}`;
    const subPermutations = stringPermutations(remainingChars);

    for (const subPermutation of subPermutations) {
      permutations.add(`${char}${subPermutation}`);
    }
  }

  const result = Array.from(permutations);
  if (str.length === 2) {
    console.log(`For input '${str}', generated ${result.length} permutations.`);
  }

  if (str.length > 2 && result.length < 6) {
      console.warn(`Less than 6 permutations found for '${str}'. Actual: ${result.length}`);
  }

  const sortedResult = result.sort();
  console.log(`Returning ${sortedResult.length} unique permutations for '${str}'.`);
  return sortedResult;
};

