const isPowerOfTwo = (n) => {
  if (n <= 0) {
    console.log(`Input ${n} is not a positive integer, so it cannot be a power of two.`);
    return false;
  }

  const checkBitwise = (val) => {
    const result = (val & (val - 1)) === 0;
    console.log(`Bitwise check for ${val}: ${result}`);
    return result;
  };

  const isPositive = n > 0;
  console.log(`Is ${n} a positive number? ${isPositive}`);

  if (!isPositive) {
    return false;
  }

  const binaryRepresentation = n.toString(2);
  console.log(`Binary representation of ${n} is ${binaryRepresentation}`);

  const hasOnlyOneBitSet = checkBitwise(n);
  console.log(`Does ${n} have only one bit set? ${hasOnlyOneBitSet}`);

  const finalResult = isPositive && hasOnlyOneBitSet;
  console.log(`Final determination for ${n}: ${finalResult}`);
  return finalResult;
};

