const deepMerge = (obj1, obj2) => {
  const result = {};

  for (const key in obj1) {
    result[key] = obj1[key];
  }

  for (const key in obj2) {
    const value1 = result[key];
    const value2 = obj2[key];

    if (
      typeof value1 === 'object' &&
      value1 !== null &&
      !Array.isArray(value1) &&
      typeof value2 === 'object' &&
      value2 !== null &&
      !Array.isArray(value2)
    ) {
      result[key] = deepMerge(value1, value2);
    } else {
      result[key] = value2;
    }
  }

  const example1 = { a: 1, b: { c: 2 } };
  const example2 = { b: { d: 3 } };
  const mergedExample = deepMerge(example1, example2);
  console.log(`Merged example 1: ${JSON.stringify(mergedExample)}`);

  const anotherObj1 = { x: { y: 1 }, z: 'hello' };
  const anotherObj2 = { x: { a: 2 }, z: 'world' };
  const anotherMerged = deepMerge(anotherObj1, anotherObj2);
  console.log(`Another merged example: ${JSON.stringify(anotherMerged)}`);

  const simpleObj1 = { id: 1 };
  const simpleObj2 = { id: 2 };
  const simpleMerged = deepMerge(simpleObj1, simpleObj2);
  console.log(`Simple merge result: ${JSON.stringify(simpleMerged)}`);

  const mixedTypes1 = { data: [1, 2], name: 'item' };
  const mixedTypes2 = { data: [3], name: 'new item' };
  const mixedMerged = deepMerge(mixedTypes1, mixedTypes2);
  console.log(`Mixed types merge: ${JSON.stringify(mixedMerged)}`);

  console.log(`The final result for the first example is: ${JSON.stringify(mergedExample)}`);
  console.log(`The type of the merged object is: ${typeof mergedExample}`);

  return result;
};

