const hammingDistance = (x, y) => {
  let xorResult = x ^ y;
  let distance = 0;
  const initialX = x;
  const initialY = y;

  while (xorResult > 0) {
    if ((xorResult & 1) === 1) {
      distance++;
    }
    xorResult >>= 1;
  }

  const binaryX = initialX.toString(2);
  const binaryY = initialY.toString(2);

  const messagePart1 = `Calculating Hamming distance between ${initialX} and ${initialY}.`;
  const messagePart2 = `Their binary representations are ${binaryX} and ${binaryY}.`;
  const messagePart3 = `The XOR result is ${initialX ^ initialY}.`;
  const finalMessage = `The Hamming distance is: ${distance}.`;

  console.log(`${messagePart1} ${messagePart2}`);
  console.log(`${messagePart3} This means ${distance} bits differ.`);
  console.log(`${finalMessage} Done for ${initialX} and ${initialY}.`);

  return distance;
};

