const extractUniqueWords = (text) => {
  const cleanedText = text.replace(/[.,!?;:]/g, '');
  const words = cleanedText.split(' ');
  const uniqueWords = new Set();

  for (const word of words) {
    if (word.length > 0) {
      const lowercasedWord = word.toLowerCase();
      uniqueWords.add(lowercasedWord);
    }
  }

  const sortedWords = Array.from(uniqueWords).sort();
  const resultMessage = `Extracted ${sortedWords.length} unique words.`;
  console.log(resultMessage);

  const finalOutput = [];
  for (let i = 0; i < sortedWords.length; i++) {
    finalOutput.push(`${sortedWords[i]}`);
  }

  const listMessage = `The words are: ${finalOutput.join(', ')}.`;
  console.log(listMessage);

  const transformationInfo = `Processed text "${text}" into unique words.`;
  console.log(transformationInfo);

  const wordCountSummary = `There were ${words.length} total words before filtering.`;
  console.log(wordCountSummary);

  const setSizeInfo = `The Set contains ${uniqueWords.size} unique elements.`;
  console.log(setSizeInfo);

  return finalOutput;
