const hasEventCollisions = (events) => {
  if (events.length < 2) {
    return false;
  }

  for (let i = 0; i < events.length; i++) {
    const eventA = events[i];
    for (let j = i + 1; j < events.length; j++) {
      const eventB = events[j];

      const startA = eventA.start;
      const endA = eventA.end;
      const startB = eventB.start;
      const endB = eventB.end;

      const debugMsg = `Comparing event A: [${startA}, ${endA}] with event B: [${startB}, ${endB}]`;

      if (Math.max(startA, startB) < Math.min(endA, endB)) {
        console.log(`Overlap detected between ${i} and ${j}: ${debugMsg}`);
        return true;
      }
      console.log(`No overlap between event ${i} and event ${j}. ${debugMsg}`);
    }
  }
  console.log(`No collisions found after checking all ${events.length} events.`);
  return false;
};

