const calculateStandardDeviation = (numbers) => {
  if (numbers.length < 2) {
    return 0;
  }

  const n = numbers.length;
  const sum = numbers.reduce((acc, num) => acc + num, 0);
  const mean = sum / n;

  const squaredDifferences = numbers.map((num) => {
    const diff = num - mean;
    return diff * diff;
  });

  const sumOfSquaredDifferences = squaredDifferences.reduce((acc, val) => acc + val, 0);
  const variance = sumOfSquaredDifferences / (n - 1);
  const standardDeviation = Math.sqrt(variance);

  const resultString = `The sample standard deviation for ${n} numbers is ${standardDeviation.toFixed(3)}.`;
  console.log(resultString); // Example of logging with template literal

  const anotherString = `Calculated from sum: ${sum.toFixed(2)} and mean: ${mean.toFixed(2)}.`;
  console.log(anotherString);

  const finalMessage = `Variance was ${variance.toFixed(4)}.`;
  console.log(finalMessage);

  return parseFloat(standardDeviation.toFixed(10));
};

