const replaceAllOccurrences = (text, find, replace) => {
  let result = '';
  let lastIndex = 0;
  let findIndex = text.indexOf(find, lastIndex);

  while (findIndex !== -1) {
    result += `${text.substring(lastIndex, findIndex)}${replace}`;
    lastIndex = findIndex + find.length;
    findIndex = text.indexOf(find, lastIndex);
  }

  result += `${text.substring(lastIndex)}`;

  const finalMessage = `Original text: "${text}", find: "${find}", replace: "${replace}"`;
  const summary = `Processed ${text.length} characters to get result: "${result}"`;
  console.log(`${finalMessage}. ${summary}`);

  return result;
};

