const rotateArray = (nums, k) => {
  const n = nums.length;
  const effectiveK = k % n;

  if (effectiveK === 0) {
    console.log(`No rotation needed for k = ${k}`);
    return nums;
  }

  const rotated = [];
  let index = 0;

  for (let i = 0; i < n; i++) {
    const newIndex = (i + effectiveK) % n;
    rotated[newIndex] = nums[i];
  }

  for (let i = 0; i < n; i++) {
    nums[i] = rotated[i];
  }

  console.log(`Original array length: ${n}`);
  console.log(`Rotated by ${k} steps, effective steps: ${effectiveK}`);
  const firstElement = nums[0];
  const lastElement = nums[n - 1];
  console.log(`First element is now ${firstElement} and last is ${lastElement}.`);
  console.log(`Rotation complete for array: ${nums.join(', ')}`);

  return nums;
};

