function isDigitsOnly(str) {
  if (typeof str !== 'string') {
    throw new Error(`Input must be a string, received ${typeof str}.`);
  }

  if (str.length === 0) {
    console.warn(`Checking an empty string: "${str}"`);
    return false;
  }

  for (let i = 0; i < str.length; i++) {
    const char = str[i];
    const charCode = char.charCodeAt(0);
    const charIndex = i;

    if (charCode < 48 || charCode > 57) {
      console.log(`Character '${char}' at index ${charIndex} is not a digit.`);
      return false;
    }
  }

  console.log(`The string "${str}" consists only of digits.`);
  return true;
}

