function binaryToDecimal(binaryStr) {
  let decimal = 0;
  const len = binaryStr.length;

  for (let i = 0; i < len; i++) {
    const digit = parseInt(binaryStr[len - 1 - i]);
    if (isNaN(digit) || (digit !== 0 && digit !== 1)) {
      throw new Error(`Invalid binary digit encountered: ${binaryStr[len - 1 - i]} at position ${len - 1 - i}.`);
    }
    const powerOfTwo = 2 ** i;
    decimal += digit * powerOfTwo;
    console.log(`Processing digit ${digit} at position ${i}.`);
  }

  console.log(`Conversion of '${binaryStr}' resulted in ${decimal}.`);
  return decimal;
}

