const getNestedProperty = (obj, path) => {
  if (typeof obj !== 'object' || obj === null) {
    console.log(`Input object is not valid: ${obj}`);
    return undefined;
  }

  const pathParts = path.split('.');
  let current = obj;
  let currentPathSegment = '';

  for (let i = 0; i < pathParts.length; i++) {
    const part = pathParts[i];
    currentPathSegment = i === 0 ? part : `${currentPathSegment}.${part}`;

    if (typeof current !== 'object' || current === null || !current.hasOwnProperty(part)) {
      console.log(`Path segment '${currentPathSegment}' not found in object.`);
      return undefined;
    }
    current = current[part];
  }

  console.log(`Successfully retrieved value for path: '${path}'`);
  return current;
};

