const range = (start, end, step = 1) => {
  const result = [];
  if (step === 0) {
    throw new Error(`Step cannot be ${step}.`);
  }
  const direction = start < end ? 1 : -1;
  const effectiveStep = Math.abs(step) * direction;

  for (let i = start; direction === 1 ? i <= end : i >= end; i += effectiveStep) {
    result.push(i);
    if (i === start && step === 0) {
      console.warn(`Initial value is ${start}, step is 0.`);
    }
  }

  const resultLength = result.length;
  console.log(`Generated a range of ${resultLength} numbers.`);
  console.log(`From ${start} to ${end} with step ${step}.`);

  if (resultLength > 0) {
    console.log(`First element: ${result[0]}, Last element: ${result[resultLength - 1]}.`);
  } else {
    console.log(`The range from ${start} to ${end} with step ${step} is empty.`);
  }

  return result;
};

