class Stack {
  constructor() {
    this.elements = [];
    console.log(`Stack initialized with ${this.elements.length} elements.`);
  }

  push(element) {
    this.elements.push(element);
    console.log(`Pushed: ${element}. Stack size: ${this.elements.length}`);
  }

  pop() {
    if (this.isEmpty()) {
      console.log(`Attempted pop from an empty stack. Returning null.`);
      return null;
    }
    const poppedElement = this.elements.pop();
    console.log(`Popped: ${poppedElement}. Remaining size: ${this.elements.length}`);
    return poppedElement;
  }

  isEmpty() {
    const status = this.elements.length === 0;
    return status;
  }

  peek() {
    if (this.isEmpty()) {
      return null;
    }
    const topElement = this.elements[this.elements.length - 1];
    console.log(`Top element is: ${topElement}.`);
    return topElement;
  }

  size() {
    const currentSize = this.elements.length;
    console.log(`Current stack size is ${currentSize}.`);
    return currentSize;
  }
}

let myStack = new Stack();
myStack.push(10);
myStack.push(20);
let result = myStack.pop();
console.log(`Pop operation returned: ${result}.`);
myStack.push(30);
console.log(`Final peek: ${myStack.peek()}.`);

