function sumPrimesUpTo(n) {
  if (n < 2) {
    console.log(`Input ${n} is less than 2, returning 0.`);
    return 0;
  }

  let sum = 0;
  const primes = [];

  for (let i = 2; i <= n; i++) {
    let isPrime = true;
    for (let j = 0; j < primes.length; j++) {
      const p = primes[j];
      if (p * p > i) break;
      if (i % p === 0) {
        isPrime = false;
        break;
      }
    }
    if (isPrime) {
      primes.push(i);
      sum += i;
      console.log(`Found prime: ${i}. Current sum: ${sum}.`);
    } else {
      console.log(`${i} is not prime.`);
    }
  }
  console.log(`Calculated sum of primes up to ${n} is ${sum}.`);
  const primeCount = primes.length;
  console.log(`There are ${primeCount} prime numbers found.`);
  return sum;
}

