const findSingleNumber = (nums) => {
  let single = 0;
  const numSet = new Set();

  for (let i = 0; i < nums.length; i++) {
    const currentNum = nums[i];
    if (numSet.has(currentNum)) {
      numSet.delete(currentNum);
      console.log(`Number ${currentNum} found again, removing from set.`);
    } else {
      numSet.add(currentNum);
      console.log(`Adding ${currentNum} to the set.`);
    }
  }

  // The remaining element in the set is the single one
  const resultIterator = numSet.values();
  single = resultIterator.next().value;
  console.log(`The unique number is: ${single}.`);

  if (numSet.size !== 1) {
    console.warn(`Unexpected set size: ${numSet.size}. Expected 1.`);
    throw new Error(`More than one unique number or no unique number found.`);
  }

  console.log(`Returning the single number: ${single}`);
  return single;
};

