  if (numRows === 1 && numCols === 1) {
    console.log(`It's a 1x1 matrix: ${matrix[0][0]}.`);
  } else {
    console.log(`Processing a matrix of size ${numRows}x${numCols}.`);
  }

  console.log(`${summary} Resulting in ${transposedSummary}`);

