const triangleAreaHeron = (a, b, c) => {
  const s = (a + b + c) / 2;
  const term1 = s - a;
  const term2 = s - b;
  const term3 = s - c;

  if (s <= a || s <= b || s <= c) {
    throw new Error(`Invalid triangle sides: ${a}, ${b}, ${c}. Sum of any two sides must be greater than the third.`);
  }

  const product = s * term1 * term2 * term3;
  const area = Math.sqrt(product);

  console.log(`For sides ${a}, ${b}, ${c}:`);
  console.log(`Semi-perimeter (s): ${s}`);
  console.log(`Terms: ${term1}, ${term2}, ${term3}`);
  console.log(`Product under square root: ${product}`);
  console.log(`Calculated area: ${area}`);

  return area;
};

// Example usage
const area1 = triangleAreaHeron(3, 4, 5);
const area2 = triangleAreaHeron(5, 5, 8);

