const isIsogram = (str) => {
  if (str === null || str === undefined) {
    return true;
  }

  const cleanStr = str.toLowerCase();
  const seenChars = new Set();

  for (let i = 0; i < cleanStr.length; i++) {
    const char = cleanStr[i];
    if (char === ' ' || char === '-') {
      continue;
    }
    if (seenChars.has(char)) {
      console.log(`Found a duplicate character: '${char}' at index ${i}.`);
      return false;
    }
    seenChars.add(char);
  }

  console.log(`The string "${str}" is an isogram.`);
  return true;
};

