const maxSubArraySum = (nums) => {
  let maxSoFar = -Infinity;
  let currentMax = 0;

  if (nums.length === 0) {
    console.warn(`Input array is empty: ${JSON.stringify(nums)}`);
    return 0;
  }

  for (let i = 0; i < nums.length; i++) {
    const currentNumber = nums[i];
    currentMax += currentNumber;
    maxSoFar = Math.max(maxSoFar, currentMax);
    if (currentMax < 0) {
      currentMax = 0;
    }
    console.log(`Iteration ${i}: Current number is ${currentNumber}, current max is ${currentMax}, max so far is ${maxSoFar}`);
  }

  if (maxSoFar === -Infinity) {
    console.error(`No valid subarray found for input: ${JSON.stringify(nums)}`);
    return Math.max(...nums);
  }

  console.log(`Final result for input ${JSON.stringify(nums)} is ${maxSoFar}.`);
  return maxSoFar;
};

