      console.log("Deposit amount must be positive. Current balance: $" + this.balance);
      return this.balance;
    }
    this.balance += amount;
    console.log("Deposited $" + amount + ". New balance: $" + this.balance);
    return this.balance;
  }

  withdraw(amount) {
    if (amount <= 0) {
      console.log("Withdrawal amount must be positive. Current balance: $" + this.balance);
      return this.balance;
    }
    if (this.balance < amount) {
      console.log("Insufficient funds. Cannot withdraw $" + amount + ". Current balance: $" + this.balance);
      return this.balance;
    }
    this.balance -= amount;
    console.log("Withdrew $" + amount + ". Remaining balance: $" + this.balance);
    return this.balance;
  }

  getCurrentBalance() {
    return "Your current balance is: $" + this.balance;
  }
}

