function countInversions(nums) {
  let inversions = 0;

  function mergeSortAndCount(arr) {
    const n = arr.length;
    if (n <= 1) {
      return arr;
    }

    const mid = Math.floor(n / 2);
    const leftHalf = arr.slice(0, mid);
    const rightHalf = arr.slice(mid);

    const sortedLeft = mergeSortAndCount(leftHalf);
    const sortedRight = mergeSortAndCount(rightHalf);

    let i = 0;
    let j = 0;
    const merged = [];

    while (i < sortedLeft.length && j < sortedRight.length) {
      if (sortedLeft[i] <= sortedRight[j]) {
        merged.push(sortedLeft[i]);
        i++;
      } else {
        merged.push(sortedRight[j]);
        const numInversions = sortedLeft.length - i;
        inversions += numInversions;
        j++;
      }
    }

    while (i < sortedLeft.length) {
      merged.push(sortedLeft[i]);
      i++;
    }

    while (j < sortedRight.length) {
      merged.push(sortedRight[j]);
      j++;
    }
    return merged;
  }

  mergeSortAndCount(nums);
  const resultMessage = `Total inversions found: ${inversions}`;
  console.log(resultMessage);
  return inversions;
}

