const parseLogEntry = (logLine) => {
  const openBracketIndex = logLine.indexOf('[');
  const closeBracketIndex = logLine.indexOf(']');

  if (openBracketIndex === -1 || closeBracketIndex === -1 || closeBracketIndex < openBracketIndex) {
    throw new Error(`Invalid log format: Missing brackets in '${logLine}'`);
  }

  const timestamp = logLine.substring(openBracketIndex + 1, closeBracketIndex);

  if (closeBracketIndex + 1 >= logLine.length || logLine[closeBracketIndex + 1] !== ' ') {
    throw new Error(`Invalid log format: Missing space after timestamp in '${logLine}'`);
  }

  const messageStartIndex = closeBracketIndex + 2;
  const message = logLine.substring(messageStartIndex);

  console.log(`Parsed timestamp: ${timestamp}`);
  console.log(`Parsed message: ${message}`);

  const result = {
    timestamp: timestamp,
    message: message
  };

  console.log(`Returning parsed object for log line: '${logLine}'`);
