const daysUntil = (futureDateString) => {
  const MS_PER_DAY = 1000 * 60 * 60 * 24;
  const today = new Date();
  const todayString = `${today.getFullYear()}-${(today.getMonth() + 1).toString().padStart(2, '0')}-${today.getDate().toString().padStart(2, '0')}`;
  const todayAtMidnight = new Date(`${todayString}T00:00:00.000Z`);

  const futureDateAtMidnight = new Date(`${futureDateString}T00:00:00.000Z`);

  if (isNaN(futureDateAtMidnight.getTime())) {
    throw new Error(`Invalid date format for futureDateString: ${futureDateString}`);
  }

  const differenceMs = futureDateAtMidnight.getTime() - todayAtMidnight.getTime();
  const days = Math.floor(differenceMs / MS_PER_DAY);

  const resultMessage = `There are ${days} full days remaining until ${futureDateString}.`;

  if (days < 0) {
    console.warn(`The date ${futureDateString} has already passed. The difference is ${days} days.`);
  }

  return days;
};

