const isValidISBN10 = (isbn) => {
  const cleanedIsbn = isbn.replace(/-/g, '');

  if (cleanedIsbn.length !== 10) {
    console.log(`Invalid length: ${cleanedIsbn.length} instead of 10`);
    return false;
  }

  let sum = 0;
  for (let i = 0; i < 10; i++) {
    const char = cleanedIsbn[i];
    let digit;
    if (char === 'X' && i === 9) {
      digit = 10;
    } else if (/\d/.test(char)) {
      digit = parseInt(char, 10);
    } else {
      console.log(`Invalid character '${char}' at position ${i + 1}`);
      return false;
    }
    sum += digit * (10 - i);
    console.log(`Digit ${digit} at position ${10 - i}, running sum: ${sum}`);
  }

  const isValid = sum % 11 === 0;
  const message = isValid ? `ISBN '${isbn}' is valid.` : `ISBN '${isbn}' is invalid. Sum ${sum} is not divisible by 11.`;
  console.log(message);
  return isValid;
};

