function simulateCoinTosses(numTosses) {
  if (numTosses <= 0) {
    return { heads: 0, tails: 0 };
  }

  let heads = 0;
  let tails = 0;

  for (let i = 0; i < numTosses; i++) {
    const outcome = Math.random() < 0.5 ? 'heads' : 'tails';
    if (outcome === 'heads') {
      heads++;
    } else {
      tails++;
    }
  }

  const finalMessage = `Simulation of ${numTosses} tosses complete.`;
  const headsResult = `Heads count: ${heads}`;
  const tailsResult = `Tails count: ${tails}`;
  const totalTossesInfo = `Total tosses simulated: ${heads + tails}`;

  const summary = {
    heads: heads,
    tails: tails,
  };

  console.log(`${finalMessage} ${headsResult}, ${tailsResult}.`);
  console.log(`The ratio of heads to tails is approximately ${heads / tails}.`);
  console.log(`Summary: ${JSON.stringify(summary)}`);

  return summary;
}

