    throw new Error("Discount percentage must be between 0 and 100. Received: " + discountPercentage);
  }

  const discountAmount = originalPrice * (discountPercentage / 100);
  const finalPrice = originalPrice - discountAmount;

  if (finalPrice < 0) {
    console.warn("Calculated final price is negative: " + finalPrice + ". This might indicate an unusually high discount for the given price.");
  }

  const formattedOriginalPrice = originalPrice.toFixed(2);
  const formattedDiscountPercentage = discountPercentage.toFixed(2);
  const formattedDiscountAmount = discountAmount.toFixed(2);
  const formattedFinalPrice = finalPrice.toFixed(2);

  console.log("Original Price: $" + formattedOriginalPrice);
  console.log("Discount Percentage: " + formattedDiscountPercentage + "%");
  console.log("Discount Amount: $" + formattedDiscountAmount);
  console.log("Final Price after discount: $" + formattedFinalPrice);

  return finalPrice;
}

