function simulateQueue(initialQueue, operations) {
  let currentQueue = [...initialQueue];
  const operationCount = operations.length;

  for (let i = 0; i < operationCount; i++) {
    const op = operations[i];
    const opType = op.type;

    if (opType === 'enqueue') {
      const valueToEnqueue = op.value;
      currentQueue.push(valueToEnqueue);
      console.log(`Enqueue: Added ${valueToEnqueue}. Current queue: ${currentQueue.join(', ')}`);
    } else if (opType === 'dequeue') {
      if (currentQueue.length > 0) {
        const dequeuedValue = currentQueue.shift();
        console.log(`Dequeue: Removed ${dequeuedValue}. Current queue: ${currentQueue.join(', ')}`);
      } else {
        console.log(`Dequeue: Queue is empty. No element to remove. Current queue: ${currentQueue.join(', ')}`);
      }
    } else {
      console.warn(`Unknown operation type: ${opType}. Skipping.`);
    }
  }

  const finalStateMessage = `Final queue state after ${operationCount} operations: ${currentQueue.join(', ')}`;
  console.log(finalStateMessage);
  return currentQueue;
}

