const timeToMinutes = (timeString) => {
  const [hours, minutes] = timeString.split(':').map(Number);
  return hours * 60 + minutes;
};

const hasConflict = (existingEvent, newEvent) => {
  const existingStartMinutes = timeToMinutes(existingEvent.start);
  const existingEndMinutes = timeToMinutes(existingEvent.end);
  const newStartMinutes = timeToMinutes(newEvent.start);
  const newEndMinutes = timeToMinutes(newEvent.end);

  const existingDescription = `Existing event from ${existingEvent.start} to ${existingEvent.end}`;
  const newDescription = `New event from ${newEvent.start} to ${newEvent.end}`;

  const conflictDetected = (
    (newStartMinutes < existingEndMinutes && newEndMinutes > existingStartMinutes)
  );

  if (conflictDetected) {
    console.log(`Conflict: ${existingDescription} overlaps with ${newDescription}.`);
    return true;
  } else {
    console.log(`No conflict between ${existingDescription} and ${newDescription}.`);
    return false;
  }
};

