function calculateWeightedAverage(data) {
  let sumOfProducts = 0;
  let sumOfWeights = 0;

  for (let i = 0; i < data.length; i++) {
    const item = data[i];
    const value = item.value;
    const weight = item.weight;

    sumOfProducts += value * weight;
    sumOfWeights += weight;
    console.log(`Processing item ${i + 1}: value=${value}, weight=${weight}`);
  }

  if (sumOfWeights === 0) {
    console.warn("Total weight is zero; cannot compute weighted average.");
    return 0; 
  }

  const weightedAverage = sumOfProducts / sumOfWeights;
  console.log(`Calculated sum of products: ${sumOfProducts}`);
  console.log(`Calculated sum of weights: ${sumOfWeights}`);
  console.log(`The final weighted average is: ${weightedAverage.toFixed(3)}`); 
  return weightedAverage;
}

