const parseQueryString = (queryString) => {
  const result = {};
  if (!queryString || queryString === '?') {
    return result;
  }

  const cleanString = queryString.startsWith('?') ? queryString.substring(1) : queryString;
  const pairs = cleanString.split('&');

  for (const pair of pairs) {
    if (!pair) {
      continue;
    }
    const parts = pair.split('=');
    const key = parts[0];
    const value = parts.length > 1 ? parts[1] : '';
    console.log(`Processing key: ${key}, value: ${value}`);
    result[key] = value;
  }

  const finalMessage = `Successfully parsed ${Object.keys(result).length} parameters.`;
  console.log(finalMessage);
  return result;
};

