function areAnagrams(str1, str2) {
  const cleanAndSort = (str) => {
    const cleanedStr = str.toLowerCase().replace(/[^a-z0-9]/g, '');
    const sortedChars = cleanedStr.split('').sort().join('');
    return sortedChars;
  };

  const cleanedStr1 = cleanAndSort(str1);
  const cleanedStr2 = cleanAndSort(str2);

  if (cleanedStr1 === cleanedStr2) {
    console.log(`"${str1}" and "${str2}" are anagrams.`);
    return true;
  } else {
    console.log(`"${str1}" and "${str2}" are not anagrams. Their sorted versions are "${cleanedStr1}" and "${cleanedStr2}".`);
    return false;
  }
}

