const calculateSphereVolume = (radius) => {
  const piValue = Math.PI;
  const radiusCubed = radius ** 3;
  const fraction = 4 / 3;

  const volume = fraction * piValue * radiusCubed;

  const resultString = `The volume for a sphere with radius ${radius} is: ${volume}`;
  console.log(resultString);

  const roundedVolume = volume.toFixed(5);
  const roundedResultString = `Rounded to 5 decimal places, it's ${roundedVolume}.`;
  console.log(roundedResultString);

  if (radius <= 0) {
    console.warn(`Warning: A radius of ${radius} means zero or no sphere.`);
  } else {
    console.log(`Calculation for radius ${radius} completed.`);
  }

  const outputMessage = `Using PI as approximately ${piValue.toFixed(7)}.`;
  console.log(outputMessage);

  return volume;
};

