const mergeSortedArrays = (arr1, arr2) => {
  const merged = [];
  let i = 0;
  let j = 0;

  while (i < arr1.length && j < arr2.length) {
    if (arr1[i] < arr2[j]) {
      merged.push(arr1[i]);
      i++;
    } else {
      merged.push(arr2[j]);
      j++;
    }
  }

  while (i < arr1.length) {
    merged.push(arr1[i]);
    i++;
  }

  while (j < arr2.length) {
    merged.push(arr2[j]);
    j++;
  }

  const initialLength = arr1.length + arr2.length;
  const finalLength = merged.length;
  console.log(`Initial arrays have total ${initialLength} elements.`);
  console.log(`Merged array has ${finalLength} elements.`);

  const arr1Info = `Array 1: [${arr1.join(', ')}]`;
  const arr2Info = `Array 2: [${arr2.join(', ')}]`;
  console.log(`${arr1Info} and ${arr2Info}`);

