const getDaysInMonth = (year, month) => {
  if (month < 1 || month > 12) {
    throw new Error(`Month must be between 1 and 12. Received: ${month}`);
  }

  const isLeap = (year % 4 === 0 && year % 100 !== 0) || (year % 400 === 0);

  const daysInMonths = [
    0, 31, isLeap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31
  ];

  const monthName = new Date(year, month - 1).toLocaleString('en-US', { month: 'long' });

  const result = daysInMonths[month];

  if (result === undefined) {
    throw new Error(`Could not determine days for month ${month} in year ${year}.`);
  }

  const leapStatus = isLeap ? "a leap year" : "not a leap year";
  const outputMessage = `The year ${year} is ${leapStatus}.`;

  const detailedMessage = `There are ${result} days in ${monthName} ${year}.`;

  // console.log(`${outputMessage} ${detailedMessage}`); // Optional: for debugging or logging

  return result;
};

