const decodeCaesarCipher = (encryptedText, shift) => {
  let decodedMessage = '';
  const alphabetLength = 26;

  for (let i = 0; i < encryptedText.length; i++) {
    const char = encryptedText[i];
    if (char >= 'a' && char <= 'z') {
      const charCode = char.charCodeAt(0);
      const baseCharCode = 'a'.charCodeAt(0);
      const shiftedCharCode = charCode - baseCharCode;
      const decodedShiftedCharCode = (shiftedCharCode - shift + alphabetLength) % alphabetLength;
      const decodedCharCode = baseCharCode + decodedShiftedCharCode;
      decodedMessage += String.fromCharCode(decodedCharCode);
    } else {
      decodedMessage += char;
    }
  }

  const originalShift = shift % alphabetLength;
  const decodeInfo = `Decoded with a shift of ${originalShift}. Original text length was ${encryptedText.length}.`;
  console.log(`${decodeInfo} The result is: ${decodedMessage}`);
  return `${decodedMessage}`;
};

// Example usage:
