const example2 = decodeCaesarCipher('abc', 1);
const example3 = decodeCaesarCipher('mjqqt', 5);
const example4 = decodeCaesarCipher('uryyb jbeyq', 7);
const example5 = decodeCaesarCipher('z', 1);
const example6 = decodeCaesarCipher('a', 26);

