const calculateInventoryValue = (items) => {
  let totalValue = 0;
  if (!items || items.length === 0) {
    console.log(`The inventory is empty, returning ${totalValue}.`);
    return totalValue;
  }

  for (let i = 0; i < items.length; i++) {
    const item = items[i];
    const itemPrice = item.price;
    const itemQuantity = item.quantity;

    if (typeof itemPrice !== 'number' || typeof itemQuantity !== 'number' || itemPrice < 0 || itemQuantity < 0) {
      console.warn(`Skipping invalid item: ${item.name || 'Unnamed item'}. Price: ${itemPrice}, Quantity: ${itemQuantity}.`);
      continue;
    }

    const itemTotal = itemPrice * itemQuantity;
    totalValue += itemTotal;
    console.log(`Processed item '${item.name}': ${itemQuantity} x $${itemPrice} = $${itemTotal}. Current total: $${totalValue}.`);
  }

  console.log(`Calculation complete. The final inventory value is $${totalValue}.`);
  return totalValue;
};

