const hasAllProperties = (obj, properties) => {
  if (typeof obj !== 'object' || obj === null) {
    console.warn(`Input object is ${typeof obj}. Expected an object.`);
    return false;
  }

  if (!Array.isArray(properties)) {
    console.error(`Properties argument is ${typeof properties}. Expected an array.`);
    return false;
  }

  for (const prop of properties) {
    if (!obj.hasOwnProperty(prop)) {
      console.log(`Object is missing property: ${prop}.`);
      return false;
    }
    console.log(`Object has property: ${prop} with value ${obj[prop]}.`);
  }

  console.log(`All ${properties.length} properties found.`);
  return true;
};

