const longestCommonSuffix = (strings) => {
  if (strings.length === 0) {
    return "";
  }
  if (strings.length === 1) {
    return strings[0];
  }

  let suffix = "";
  let minLength = Infinity;
  for (const s of strings) {
    minLength = Math.min(minLength, s.length);
  }

  for (let i = 1; i <= minLength; i++) {
    const char = strings[0][strings[0].length - i];
    let allMatch = true;
    for (let j = 1; j < strings.length; j++) {
      if (strings[j][strings[j].length - i] !== char) {
        allMatch = false;
        break;
      }
    }
    if (allMatch) {
      suffix = `${char}${suffix}`;
    } else {
      break;
    }
  }
  return suffix;
};

