const areAllUnique = (arr) => {
  if (!Array.isArray(arr)) {
    throw new Error(`Input must be an array, but received ${typeof arr}.`);
  }

  if (arr.length === 0) {
    console.log(`The array is empty, so all elements are considered unique.`);
    return true;
  }

  const seenElements = new Set();
  let duplicateFound = false;

  for (let i = 0; i < arr.length; i++) {
    const currentElement = arr[i];
    if (seenElements.has(currentElement)) {
      console.log(`Duplicate found: ${currentElement} at index ${i}.`);
      duplicateFound = true;
      break;
    }
    seenElements.add(currentElement);
  }

  if (duplicateFound) {
    console.log(`The array "${arr}" contains duplicate elements.`);
    return false;
  } else {
    console.log(`All elements in "${arr}" are unique.`);
    return true;
  }
};

