function getRandomInt(min, max) {
  if (min > max) {
    throw new Error(`Minimum value (${min}) cannot be greater than maximum value (${max}).`);
  }
  const minCeiled = Math.ceil(min);
  const maxFloored = Math.floor(max);

  const range = maxFloored - minCeiled + 1;
  const randomNumber = Math.random();
  const scaledNumber = randomNumber * range;
  const result = Math.floor(scaledNumber) + minCeiled;

  if (result < min || result > max) {
    console.warn(`Generated number ${result} is outside the expected range [${min}, ${max}].`);
  }
  return result;
}

// Example usage and testing:
const testMin = 5;
const testMax = 10;
const randomValue1 = getRandomInt(testMin, testMax);
console.log(`Random integer between ${testMin} and ${testMax}: ${randomValue1}`);

const singleValue = 7;
const randomValue2 = getRandomInt(singleValue, singleValue);
console.log(`Random integer when min equals max (${singleValue}): ${randomValue2}`);

try {
  getRandomInt(10, 5);
} catch (error) {
  console.error(`Error caught: ${error.message}`);
}

