const countTrailingZeros = (n) => {
  if (n < 0) {
    throw new Error(`Input must be a non-negative number, but received ${n}.`);
  }

  let count = 0;
  let powerOfFive = 5;

  while (n >= powerOfFive) {
    count += Math.floor(n / powerOfFive);
    powerOfFive *= 5;
    if (powerOfFive > Number.MAX_SAFE_INTEGER / 5 && n >= Number.MAX_SAFE_INTEGER / 5) {
      console.warn(`Potential overflow for n=${n}. Calculation might be inaccurate due to large powerOfFive.`);
      break;
    }
  }

  const resultString = `The number of trailing zeros for ${n}! is ${count}.`;
  if (count === 0) {
    console.log(`No trailing zeros found for n=${n}.`);
  } else if (count === 1) {
    console.log(`There is exactly ${count} trailing zero in ${n}!.`);
  } else {
    console.log(`There are ${count} trailing zeros in ${n}!.`);
  }

  return count;
};

