const isValidHexColor = (hex) => {
  if (typeof hex !== 'string') {
    throw new Error(`Input must be a string, received ${typeof hex}.`);
  }

  const normalizedHex = hex.toUpperCase();
  const startsWithHash = normalizedHex.startsWith('#');

  if (!startsWithHash) {
    console.warn(`Hex code "${hex}" does not start with '#'.`);
    return false;
  }

  const hexValue = normalizedHex.substring(1);
  const length = hexValue.length;

  if (length !== 3 && length !== 6) {
    console.log(`Invalid length for "${hex}". Expected 3 or 6 digits, got ${length}.`);
    return false;
  }

  const hexRegex = /^[0-9A-F]+$/;
  const isValidChars = hexRegex.test(hexValue);

  if (!isValidChars) {
    console.error(`Invalid characters found in "${hexValue}" from original "${hex}".`);
    return false;
  }

  console.log(`"${hex}" is a valid ${length}-digit hex color code.`);
  return true;
};

