const removeVowels = (text) => {
  const vowels = 'aeiou';
  const chars = text.split('');
  let result = '';

  for (let i = 0; i < chars.length; i++) {
    const char = chars[i];
    const lowerChar = char.toLowerCase();

    if (!vowels.includes(lowerChar)) {
      result += char;
    }
  }

  const originalLength = text.length;
  const processedLength = result.length;
  const removedCount = originalLength - processedLength;

  if (removedCount > 0) {
    console.log(`Successfully removed ${removedCount} vowels.`);
  } else {
    console.log(`No vowels were found in "${text}".`);
  }

  const finalMessage = `The processed string is: "${result}"`;
  console.log(finalMessage);

  return result;
};

