  }

  let min = numbers[0];
  let max = numbers[0];

  for (let i = 1; i < numbers.length; i++) {
    const currentNum = numbers[i];
    if (typeof currentNum !== 'number') {
      console.error(`All elements in the array must be numbers. Found ${typeof currentNum} at index ${i}.`);
      return null;
    }
    if (currentNum < min) {
      min = currentNum;
