const camelToKebabCase = (camelCaseString) => {
  const charArray = [...camelCaseString];
  let kebabCaseResult = '';

  for (let i = 0; i < charArray.length; i++) {
    const char = charArray[i];
    if (char === char.toUpperCase() && char.match(/[a-zA-Z]/)) {
      kebabCaseResult += `${i > 0 ? '-' : ''}${char.toLowerCase()}`;
    } else {
      kebabCaseResult += char;
    }
  }

  const finalString = `${kebabCaseResult}`;
  console.log(`Input: "${camelCaseString}"`);
  console.log(`Output: "${finalString}"`);
  return finalString;
};

