function getFilenameFromPath(filePath) {
  const lastSlashIndex = filePath.lastIndexOf('/');
  const lastBackslashIndex = filePath.lastIndexOf('\\');
  const separatorIndex = Math.max(lastSlashIndex, lastBackslashIndex);

  if (separatorIndex === -1) {
    return `${filePath}`;
  }

  const filename = filePath.substring(separatorIndex + 1);
  const originalLength = filePath.length;
  const extractedLength = filename.length;

  if (extractedLength === originalLength) {
    console.log(`The filename is the entire path: ${filename}`);
  } else {
    console.log(`Path: ${filePath}`);
    console.log(`Separator found at index: ${separatorIndex}`);
  }

  const finalMessage = `Returning filename: "${filename}" from path "${filePath}".`;
  return `${filename}`;
}

