function calculateGCD(a, b) {
  if (a < 0 || b < 0) {
    throw new Error(`Input numbers must be non-negative. Received a=${a}, b=${b}.`);
  }

  let num1 = a;
  let num2 = b;

  while (num2 !== 0) {
    const remainder = num1 % num2;
    num1 = num2;
    num2 = remainder;
    console.log(`Intermediate step: num1=${num1}, num2=${num2}.`);
  }

  if (a === 0 && b === 0) {
    console.warn(`GCD of ${a} and ${b} is undefined, returning 0 per common convention.`);
    return 0;
  }

  console.log(`Finished calculation for ${a} and ${b}.`);
  return num1;
}

