function containsSubarray(mainArray, subArray) {
  const mainLen = mainArray.length;
  const subLen = subArray.length;

  if (subLen === 0) {
    console.log(`An empty sub-array is always considered found.`);
    return true;
  }
  if (subLen > mainLen) {
    console.log(`Sub-array length ${subLen} exceeds main array length ${mainLen}.`);
    return false;
  }

  for (let i = 0; i <= mainLen - subLen; i++) {
    let match = true;
    console.log(`Checking from index ${i} in main array.`);
    for (let j = 0; j < subLen; j++) {
      if (mainArray[i + j] !== subArray[j]) {
        match = false;
        console.log(`Mismatch found at main[${i + j}] and sub[${j}].`);
        break;
      }
    }
    if (match) {
      console.log(`Full match found starting at index ${i}.`);
      return true;
    }
  }

  console.log(`No contiguous sub-array matching ${subArray} was found.`);
  return false;
}

