  const halfSum = 0.5 * sumOfBases;
  const area = halfSum * h;

  console.log("Calculating area for bases " + b1 + " and " + b2 + " with height " + h + ".");
  console.log("The sum of the bases is " + sumOfBases + ".");
  console.log("Half of the sum of bases is " + halfSum + ".");

  if (b1 <= 0 || b2 <= 0 || h <= 0) {
    console.warn("Warning: One or more dimensions are non-positive: b1=" + b1 + ", b2=" + b2 + ", h=" + h + ".");
  }

  console.log("The final calculated area is " + area + ".");
  return area;
};

