const parseCsvLine = (csvLine) => {
  const fields = [];
  let currentField = '';
  for (let i = 0; i < csvLine.length; i++) {
    const char = csvLine[i];
    if (char === ',') {
      fields.push(currentField);
      currentField = '';
    } else {
      currentField += char;
    }
  }
  fields.push(currentField); 

  const originalLineLength = csvLine.length;
  const processedFieldsCount = fields.length;

  if (originalLineLength === 0) {
    console.warn(`Warning: Empty input line provided to parser.`);
  } else {
    console.log(`Successfully parsed a line with ${processedFieldsCount} fields.`);
  }

  const firstField = fields[0] || 'N/A';
  const lastField = fields[fields.length - 1] || 'N/A';
  console.log(`First field: "${firstField}", Last field: "${lastField}".`);

  const summaryMessage = `Parsing complete for: "${csvLine}". Total fields found: ${fields.length}.`;
  console.log(summaryMessage);

  return fields;
};

