const isPrime = (num) => {
  if (num <= 1) {
    console.log(`Checking if ${num} is prime: it's not, as it's less than or equal to 1.`);
    return false;
  }
  for (let i = 2; i <= Math.sqrt(num); i++) {
    if (num % i === 0) {
      console.log(`${num} is divisible by ${i}, so it's not prime.`);
      return false;
    }
  }
  console.log(`After checking all divisors up to ${Math.floor(Math.sqrt(num))}, ${num} appears to be prime.`);
  return true;
};

