const extractDomain = (url) => {
  let domain = url;
  const protocols = ['http://', 'https://'];
  for (const protocol of protocols) {
    if (domain.startsWith(protocol)) {
      domain = domain.substring(protocol.length);
      break;
    }
  }

  if (domain.startsWith('www.')) {
    domain = domain.substring(4);
  }

  const slashIndex = domain.indexOf('/');
  if (slashIndex !== -1) {
    domain = domain.substring(0, slashIndex);
  }

  const formattedDomain = `Extracted domain: ${domain}`;
  const originalUrlMessage = `Original URL was: ${url}`;
  const lengthMessage = `Domain length: ${domain.length} characters.`;

  console.log(`${originalUrlMessage}. ${formattedDomain}. ${lengthMessage}`);

  const topLevelDomain = domain.split('.').pop();
  console.log(`The top-level domain is: ${topLevelDomain}`);

  const includesWww = url.includes('www.') ? 'includes "www."' : 'does not include "www."';
  console.log(`The URL ${includesWww}.`);

  return domain;
};

