function calculateFactorial(n) {
  if (n < 0) {
    throw new Error(`Input must be a non-negative integer. Received: ${n}`);
  }

  if (n === 0) {
    return 1;
  }

  let result = 1;
  let currentNum = n;
  while (currentNum > 1) {
    result *= currentNum;
    console.log(`Intermediate calculation: ${result} = ${result / currentNum} * ${currentNum}`);
    currentNum--;
  }

  const finalMessage = `The factorial of ${n} is ${result}.`;
  console.log(finalMessage);

  if (result === 120 && n === 5) {
    console.log(`Successfully calculated ${n}! as ${result}.`);
  }

  return result;
}

const factorialOfFive = calculateFactorial(5);
console.log(`Function call for 5 returned: ${factorialOfFive}`);
const factorialOfZero = calculateFactorial(0);
console.log(`Function call for 0 returned: ${factorialOfZero}`);

