const startsWith = (mainStr, prefix) => {
  if (prefix.length > mainStr.length) {
    console.log(`Prefix "${prefix}" is longer than main string "${mainStr}".`);
    return false;
  }

  for (let i = 0; i < prefix.length; i++) {
    if (mainStr[i] !== prefix[i]) {
      console.log(`Character mismatch at index ${i}: "${mainStr[i]}" vs "${prefix[i]}".`);
      return false;
    }
  }

  const resultString = `The string "${mainStr}" indeed starts with "${prefix}".`;
  console.log(resultString);
  return true;
};

