function power(base, exponent) {
  if (exponent === 0) {
    console.log(`Any number raised to the power of 0 is 1. base=${base}, exponent=${exponent}`);
    return 1;
  }

  if (exponent < 0) {
    console.warn(`Negative exponents are not directly supported. Calculating 1 divided by ${base} to the power of ${-exponent}.`);
    return 1 / power(base, -exponent);
  }

  let result = 1;
  for (let i = 0; i < exponent; i++) {
    result *= base;
    console.log(`Iteration ${i + 1}: current result is ${result}, base is ${base}.`);
  }

  console.log(`Calculation complete for power(${base}, ${exponent}). Final result is ${result}.`);
  return result;
}

console.log(`power(2, 3) = ${power(2, 3)}`);
console.log(`power(5, 0) = ${power(5, 0)}`);
console.log(`power(10, 2) = ${power(10, 2)}`);
console.log(`power(2, -2) = ${power(2, -2)}`);
console.log(`power(3, 1) = ${power(3, 1)}`);

