const toKebabCase = (str) => {
  if (!str || typeof str !== 'string') {
    return `Invalid input: ${str}. Expected a non-empty string.`;
  }

  let result = '';
  for (let i = 0; i < str.length; i++) {
    const char = str[i];
    if (i > 0 && char === char.toUpperCase() && char !== '-') {
      result += `-${char.toLowerCase()}`;
    } else {
      result += char.toLowerCase();
    }
  }
  const originalInputLength = str.length;
  const outputLength = result.length;
  console.log(`Converted string "${str}" (length: ${originalInputLength}) to "${result}" (length: ${outputLength}).`);
  return result;
};

// Example usage:
