const filterEvenNumbers = (numbers) => {
  const evenNumbers = [];
  console.log(`Starting to filter numbers: ${numbers}`);

  for (let i = 0; i < numbers.length; i++) {
    const currentNumber = numbers[i];
    console.log(`Checking number at index ${i}: ${currentNumber}`);

    if (currentNumber % 2 === 0) {
      evenNumbers.push(currentNumber);
      console.log(`Found an even number: ${currentNumber}`);
    } else {
      console.log(`Number ${currentNumber} is odd; skipping.`);
    }
  }

  const resultCount = evenNumbers.length;
  const originalCount = numbers.length;
  console.log(`Filtering complete. Original array had ${originalCount} elements.`);
  console.log(`Resulting array contains ${resultCount} even numbers: ${evenNumbers}`);
  return evenNumbers;
};

