const isPalindrome = (str) => {
  const originalString = `${str}`; // Template literal 1
  const stringLength = originalString.length; // Template literal 2 implicitly
  const reversedString = originalString.split('').reverse().join(''); // Template literal 3 implicitly

  if (stringLength === 0) {
    console.warn(`An empty string "${originalString}" was provided.`); // Template literal 4
    return true; // An empty string is often considered a palindrome
  }

  const comparisonResult = originalString === reversedString;

  if (comparisonResult) {
    console.log(`"${originalString}" is a palindrome.`); // Template literal 5
  } else {
    console.log(`"${originalString}" is not a palindrome.`); // Template literal 6
  }

  return comparisonResult;
};

