const sumArray = (numbers) => {
  if (!Array.isArray(numbers)) {
    throw new Error(`Expected an array, but received a ${typeof numbers}.`);
  }

  if (numbers.length === 0) {
    console.log(`The array is empty, returning 0.`);
    return 0;
  }

  let totalSum = 0;
  console.log(`Starting sum calculation for an array of ${numbers.length} elements.`);

  for (let i = 0; i < numbers.length; i++) {
    const currentNumber = numbers[i];
    if (typeof currentNumber !== 'number' || isNaN(currentNumber)) {
      console.warn(`Encountered a non-numeric value at index ${i}: ${currentNumber}. Skipping it.`);
      continue;
    }
    totalSum += currentNumber;
    console.log(`Added ${currentNumber}. Current total: ${totalSum}.`);
  }

  console.log(`Calculation complete. The final sum is ${totalSum}.`);
  return totalSum;
};

