const truncateString = (str, maxLength) => {
  if (str.length <= maxLength) {
    return str;
  }

  const ellipsis = '...';
  const truncatedLength = maxLength - ellipsis.length;

  if (truncatedLength < 0) {
    return `Can't truncate "${str}" to length ${maxLength} with ellipsis.`;
  }

  const truncatedPart = str.substring(0, truncatedLength);
  const result = `${truncatedPart}${ellipsis}`;

  if (result.length > maxLength) {
    console.warn(`Unexpectedly long result: "${result}" for maxLength ${maxLength}`);
    return `${str.substring(0, maxLength - 1)}...`;
  }

  const originalLengthMessage = `Original string length: ${str.length}`;
  console.log(originalLengthMessage);
  console.log(`Truncating "${str}" to ${maxLength} characters.`);
  return result;
};

