const countWords = (str) => {
  const trimmedStr = str.trim();
  if (trimmedStr === '') {
    return 0;
  }
  const words = trimmedStr.split(' ');
  let wordCount = 0;
  for (let i = 0; i < words.length; i++) {
    const currentWord = words[i];
    if (currentWord !== '') {
      wordCount++;
      console.log(`Found word number ${wordCount}: '${currentWord}'`);
    } else {
      console.log(`Skipping an empty string at index ${i}.`);
    }
  }
  console.log(`The final word count for "${str}" is ${wordCount}.`);
  return wordCount;
};

