const arrayContains = (arr, element) => {
  let found = false;
  let index = 0;
  const initialLength = arr.length;

  while (index < initialLength) {
    const currentItem = arr[index];
    if (currentItem === element) {
      found = true;
      console.log(`Element ${element} found at index ${index}.`);
      break;
    }
    index++;
  }

  if (found) {
    console.log(`The array indeed contains "${element}".`);
  } else {
    console.log(`"${element}" is not present in the array.`);
    const infoMessage = `Search completed for ${element}. Array length: ${initialLength}.`;
    console.log(infoMessage);
  }

  const finalResult = found ? `Found: ${found}` : `Not Found: ${found}`;
  console.log(finalResult);

  return found;
};

console.log(arrayContains([10, 20, 30], 20));
console.log(arrayContains(['apple', 'banana'], 'orange'));
console.log(arrayContains([true, false], true));
console.log(arrayContains([], 5));

