const endsWith = (mainStr, suffix) => {
  const mainLength = mainStr.length;
  const suffixLength = suffix.length;

  if (suffixLength > mainLength) {
    return false;
  }

  const startIndex = mainLength - suffixLength;
  const extractedPart = mainStr.substring(startIndex);

  if (extractedPart === suffix) {
    console.log(`"${mainStr}" indeed ends with "${suffix}".`);
    return true;
  } else {
    console.log(`"${mainStr}" does not end with "${suffix}". It ends with "${extractedPart}".`);
    return false;
  }
};

const result1 = endsWith('hello world', 'world');
const result2 = endsWith('javascript', 'script');
const result3 = endsWith('apple', 'pie');
const result4 = endsWith('testing template literals', 'literals');
const result5 = endsWith('another example string', 'string');
