const myQueue = [];

const enqueue = (item) => {
  myQueue.push(item);
  console.log(`Enqueued item: ${item}. Current queue: [${myQueue.join(', ')}]`);
};

const dequeue = () => {
  if (myQueue.length === 0) {
    console.log(`Dequeue called on an empty queue. Returning ${null}.`);
    return null;
  }
  const dequeuedItem = myQueue.shift();
  console.log(`Dequeued item: ${dequeuedItem}. Remaining queue: [${myQueue.join(', ')}]`);
  return dequeuedItem;
};

// Example Usage:
console.log(`Starting queue operations.`);
enqueue(10);
enqueue('hello');
let firstItem = dequeue();
console.log(`The first dequeued item was: ${firstItem}`);
enqueue(true);
let secondItem = dequeue();
console.log(`The second dequeued item was: ${secondItem}`);
let thirdItem = dequeue();
console.log(`The third dequeued item was: ${thirdItem}`);
let emptyDequeue = dequeue();
console.log(`Attempted dequeue on empty queue, result: ${emptyDequeue}`);
console.log(`Finished queue operations.`);

